<template>
	<view v-if="product" class="detail-page">
		<swiper class="gallery" circular indicator-dots indicator-color="rgba(0,0,0,.16)" indicator-active-color="#e1251b"><swiper-item v-for="(image,index) in product.images" :key="image||index"><image v-if="image" :src="image" mode="aspectFit" /><view v-else class="gallery-placeholder">JD</view></swiper-item></swiper>
		<view class="product-summary"><view class="price-row"><view class="price"><text>¥</text>{{ formatPrice(currentPrice) }}</view><text class="sales">已售 {{ product.sales }} · 评价 {{ reviewTotal }}</text></view><text class="title">{{ product.title }}</text><text v-if="product.subtitle" class="subtitle">{{ product.subtitle }}</text><view class="service-row"><text>正品保障</text><text>极速退款</text><text>售后无忧</text></view></view>
		<view v-if="product.options.length" class="option-panel">
			<view v-for="option in product.options" :key="option.label" class="option-row"><text class="option-label">{{ option.label }}</text><view class="option-values"><text v-for="value in option.values" :key="value" class="option-value" :class="{selected:selection[option.label]===value}" @tap="selectOption(option.label,value)">{{ value }}</text></view></view>
			<view class="quantity-row"><text class="option-label">数量</text><view class="stepper"><button @tap="changeQuantity(-1)">−</button><text>{{ quantity }}</text><button @tap="changeQuantity(1)">+</button></view><text class="stock">库存 {{ currentStock }}</text></view>
		</view>
		<view v-if="product.shop" class="shop-row"><view><text class="shop-kicker">品牌店铺</text><text class="shop-name">{{ product.shop.shopName||'官方店铺' }}</text></view><text class="shop-rating">{{ product.shop.rating||'5.0' }} 分</text></view>
		<view class="detail-panel"><view class="panel-title"><text></text><text>商品详情</text><text></text></view><rich-text v-if="product.detail" :nodes="product.detail" class="rich-detail"></rich-text><StateView v-else title="暂无商品详情" /></view>
		<view class="review-panel">
			<view class="review-heading"><view><text>用户评价</text><text>{{ reviewTotal }} 条真实评价</text></view><text v-if="reviewTotal">好评优先</text></view>
			<view v-if="reviews.length" class="review-list">
				<view v-for="review in reviews" :key="review.id" class="review-item">
					<view class="review-user"><view class="review-avatar"><image v-if="review.avatar" :src="review.avatar" mode="aspectFill" /><text v-else>{{ review.name.slice(0, 1) }}</text></view><view class="review-user-copy"><text>{{ review.name }}</text><text class="review-stars">{{ '★'.repeat(review.rating) }}<text>{{ '☆'.repeat(5-review.rating) }}</text></text></view><text class="review-date">{{ formatReviewDate(review.createTime) }}</text></view>
					<text class="review-content">{{ review.content }}</text>
					<view v-if="review.images.length" class="review-images"><image v-for="(image,index) in review.images" :key="image" :src="image" mode="aspectFill" @tap="previewReviewImage(review.images,index)" /></view>
					<view v-if="review.reply" class="merchant-reply"><text>商家回复</text><text>{{ review.reply }}</text></view>
				</view>
				<button v-if="!reviewsFinished" class="review-more" :loading="reviewLoading" @tap="loadReviews()">加载更多评价</button>
				<text v-else class="review-end">已展示全部评价</text>
			</view>
			<StateView v-else-if="!reviewLoading" title="暂无评价" description="购买并完成订单后可以发表评价" />
			<view v-else class="review-loading">正在加载评价...</view>
		</view>
		<view class="action-bar"><view class="icon-action" @tap="goHome"><image src="/static/icons/home.png" mode="aspectFit" /><text>首页</text></view><view class="icon-action" @tap="goCart"><image src="/static/icons/cart.png" mode="aspectFit" /><text>购物车</text></view><view class="icon-action" @tap="toggleFavorite"><image :src="isFavorite?'/static/icons/heart-active.png':'/static/icons/heart.png'" mode="aspectFit" /><text :class="{favorite:isFavorite}">收藏</text></view><button class="cart-action" :disabled="submitting||currentStock===0" @tap="handleAddCart">加入购物车</button><button class="buy-action" :disabled="submitting||currentStock===0" @tap="buyNow">立即购买</button></view>
	</view>
	<StateView v-else-if="error" title="商品加载失败" :description="error" action-text="重新加载" error @action="loadDetail" />
	<view v-else class="detail-loading">正在加载商品...</view>
</template>

<script>
	import StateView from '../../components/StateView.vue'
	import {addFavorite,addToCart,checkFavorite,getProductDetail,getProductReviews,removeFavorite} from '../../api/index.js'
	import {formatDate,formatMoney} from '../../utils/format.js'
	import {normalizeProductDetail,normalizeReviewList} from '../../utils/normalizers.js'
	import {isLoggedIn,requireLogin} from '../../utils/auth.js'
	export default{
		components:{StateView},data(){return{id:0,product:null,selection:{},quantity:1,isFavorite:false,submitting:false,error:'',reviews:[],reviewTotal:0,reviewPage:1,reviewSize:10,reviewLoading:false,reviewsFinished:false}},
		computed:{selectedSku(){const entries=Object.entries(this.selection);return this.product?.skuList.find((sku)=>entries.length&&entries.every(([key,value])=>sku.specs[key]===value))||this.product?.skuList[0]||null},currentPrice(){return this.selectedSku?.price??this.product?.price??0},currentStock(){return this.selectedSku?this.selectedSku.stock:0}},
		onLoad(options){this.id=Number(options.id);this.loadDetail()},
		methods:{formatPrice:formatMoney,
			async loadDetail(){this.error='';try{this.product=normalizeProductDetail(await getProductDetail(this.id));const firstAvailable=this.product.skuList.find((sku)=>sku.stock>0)||this.product.skuList[0];this.selection=firstAvailable?{...firstAvailable.specs}:{};if(!this.product.images.length)this.product.images=[''];this.loadReviews(true);if(isLoggedIn())this.loadFavoriteState()}catch(error){this.error=error.message||'请稍后重试'}},
			async loadReviews(reset=false){if(this.reviewLoading)return;if(reset){this.reviews=[];this.reviewPage=1;this.reviewTotal=0;this.reviewsFinished=false}this.reviewLoading=true;try{const result=normalizeReviewList(await getProductReviews(this.id,{page:this.reviewPage,size:this.reviewSize}));this.reviews=reset?result.list:[...this.reviews,...result.list];this.reviewTotal=result.total;this.reviewsFinished=result.list.length<this.reviewSize||this.reviews.length>=this.reviewTotal;if(!this.reviewsFinished)this.reviewPage+=1}catch(error){if(!this.reviews.length)uni.showToast({title:error.message||'评价加载失败',icon:'none'})}finally{this.reviewLoading=false}},
			formatReviewDate(value){return formatDate(value).slice(0,10)},previewReviewImage(urls,index){uni.previewImage({urls,current:urls[index]})},
			async loadFavoriteState(){try{const result=await checkFavorite(this.id);this.isFavorite=Boolean(result?.favorite??result?.isFavorite??result)}catch{}},selectOption(label,value){this.selection={...this.selection,[label]:value};this.quantity=Math.min(this.quantity,Math.max(1,this.currentStock))},changeQuantity(step){this.quantity=Math.max(1,Math.min(99,this.currentStock||1,this.quantity+step))},
			validateSku(){if(!this.selectedSku?.id){uni.showToast({title:'请选择完整规格',icon:'none'});return false}if(this.selectedSku.stock<=0){uni.showToast({title:'该规格暂时缺货',icon:'none'});return false}return true},
			async handleAddCart(){if(!requireLogin(`/pages/products/detail?id=${this.id}`)||!this.validateSku())return;this.submitting=true;try{await addToCart({skuId:this.selectedSku.id,quantity:this.quantity});uni.showToast({title:'已加入购物车',icon:'success'})}catch(error){uni.showToast({title:error.message,icon:'none'})}finally{this.submitting=false}},
			buyNow(){if(!requireLogin(`/pages/products/detail?id=${this.id}`)||!this.validateSku())return;uni.navigateTo({url:`/pages/checkout/index?mode=buyNow&skuId=${this.selectedSku.id}&quantity=${this.quantity}&productId=${this.id}`})},
			async toggleFavorite(){if(!requireLogin(`/pages/products/detail?id=${this.id}`))return;try{this.isFavorite?await removeFavorite(this.id):await addFavorite(this.id);this.isFavorite=!this.isFavorite;uni.showToast({title:this.isFavorite?'已收藏':'已取消收藏',icon:'success'})}catch(error){uni.showToast({title:error.message,icon:'none'})}},goHome(){uni.switchTab({url:'/pages/index/index'})},goCart(){uni.switchTab({url:'/pages/cart/index'})},
		},
	}
</script>

<style scoped>
	.detail-page{min-height:100vh;padding-bottom:130rpx;background:#f5f6f8}.gallery{width:100%;height:750rpx;background:#fff}.gallery image,.gallery-placeholder{width:100%;height:100%}.gallery-placeholder{display:flex;align-items:center;justify-content:center;color:#fff;background:#d7dbe0;font-size:64rpx;font-weight:800}.product-summary{padding:28rpx;background:#fff}.price-row{display:flex;align-items:flex-end;justify-content:space-between}.price{color:#e1251b;font-size:48rpx;font-weight:800}.price text{margin-right:3rpx;font-size:25rpx}.sales{color:#989fa8;font-size:22rpx}.title{display:block;margin-top:20rpx;color:#25292f;font-size:34rpx;font-weight:700;line-height:1.45}.subtitle{display:block;margin-top:10rpx;color:#7d8590;font-size:25rpx;line-height:1.55}.service-row{display:flex;margin:24rpx -28rpx -28rpx;padding:20rpx 28rpx;gap:30rpx;border-top:1rpx solid #eff0f2;color:#7d8590;font-size:21rpx}.service-row text::before{color:#e1251b;content:'✓ '}.option-panel,.shop-row,.detail-panel,.review-panel{margin-top:16rpx;padding:28rpx;background:#fff}.option-row{display:flex;margin-bottom:26rpx}.option-label{width:92rpx;flex:0 0 92rpx;color:#616975;font-size:25rpx;line-height:58rpx}.option-values{display:flex;flex:1;flex-wrap:wrap;gap:14rpx}.option-value{padding:13rpx 22rpx;border:1rpx solid #e0e3e7;border-radius:7rpx;color:#3e454e;background:#f7f8f9;font-size:23rpx}.option-value.selected{border-color:#e1251b;color:#e1251b;background:#fff1f0}.quantity-row{display:flex;align-items:center}.stepper{display:flex;height:58rpx;align-items:center;border:1rpx solid #dfe2e6}.stepper button{width:58rpx;height:56rpx;margin:0;padding:0;border:0;border-radius:0;color:#525964;background:#f6f7f8;font-size:29rpx;line-height:56rpx}.stepper button::after{border:0}.stepper text{width:76rpx;text-align:center;font-size:24rpx}.stock{margin-left:18rpx;color:#9ba1aa;font-size:21rpx}.shop-row{display:flex;align-items:center;justify-content:space-between}.shop-kicker,.shop-name{display:block}.shop-kicker{color:#e1251b;font-size:19rpx;font-weight:800}.shop-name{margin-top:8rpx;color:#30353c;font-size:29rpx;font-weight:700}.shop-rating{color:#777f89;font-size:23rpx}.panel-title{display:flex;align-items:center;justify-content:center;gap:18rpx;margin-bottom:24rpx;color:#30353c;font-size:29rpx;font-weight:700}.panel-title text:first-child,.panel-title text:last-child{width:54rpx;height:1rpx;background:#dfe2e6}.rich-detail{color:#4b535e;font-size:25rpx;line-height:1.8}.review-heading{display:flex;padding-bottom:24rpx;align-items:flex-end;justify-content:space-between;border-bottom:1rpx solid #eef0f2}.review-heading view text{display:block;color:#30363e;font-size:30rpx;font-weight:700}.review-heading view text:last-child{margin-top:6rpx;color:#969da6;font-size:20rpx;font-weight:400}.review-heading>text{color:#e1251b;font-size:21rpx}.review-item{padding:28rpx 0;border-bottom:1rpx solid #eef0f2}.review-user{display:flex;align-items:center}.review-avatar{display:flex;width:68rpx;height:68rpx;flex:0 0 68rpx;align-items:center;justify-content:center;overflow:hidden;border-radius:50%;color:#e1251b;background:#fff0ee;font-size:24rpx;font-weight:700}.review-avatar image{width:100%;height:100%}.review-user-copy{min-width:0;flex:1;margin-left:14rpx}.review-user-copy>text{display:block;color:#424952;font-size:23rpx}.review-stars{margin-top:5rpx;color:#f2a51a!important;font-size:22rpx!important;letter-spacing:2rpx}.review-stars text{color:#d8dce1}.review-date{color:#a0a6ae;font-size:20rpx}.review-content{display:block;margin-top:20rpx;color:#4c545e;font-size:25rpx;line-height:1.7}.review-images{display:grid;grid-template-columns:repeat(3,1fr);gap:10rpx;margin-top:18rpx}.review-images image{width:100%;height:190rpx;border-radius:7rpx;background:#f1f2f4}.merchant-reply{margin-top:18rpx;padding:16rpx 18rpx;border-left:5rpx solid #e1251b;background:#f7f8f9}.merchant-reply text{display:block;color:#e1251b;font-size:21rpx;font-weight:700}.merchant-reply text:last-child{margin-top:7rpx;color:#666e78;font-size:22rpx;font-weight:400;line-height:1.55}.review-more{height:66rpx;margin:24rpx auto 0;border:1rpx solid #dfe2e6;border-radius:8rpx;color:#626a75;background:#fff;font-size:22rpx;line-height:66rpx}.review-more::after{border:0}.review-end{display:block;padding-top:24rpx;color:#a0a6ae;font-size:21rpx;text-align:center}.review-loading{padding:70rpx 0;color:#969da6;font-size:23rpx;text-align:center}.action-bar{position:fixed;right:0;bottom:0;left:0;z-index:20;display:grid;grid-template-columns:82rpx 82rpx 82rpx 1fr 1fr;min-height:104rpx;padding-bottom:env(safe-area-inset-bottom);border-top:1rpx solid #e5e7ea;background:#fff}.icon-action{display:flex;align-items:center;justify-content:center;flex-direction:column;color:#666e78;font-size:18rpx}.icon-action image{width:34rpx;height:34rpx;margin-bottom:5rpx}.icon-action text.favorite{color:#e1251b}.action-bar button{height:76rpx;margin:14rpx 0;border:0;border-radius:0;color:#fff;font-size:24rpx;line-height:76rpx}.action-bar button::after{border:0}.cart-action{background:#ff9f2f}.buy-action{margin-right:12rpx!important;border-radius:0 9rpx 9rpx 0!important;background:#e1251b}.action-bar button[disabled]{color:#fff;opacity:.5}.detail-loading{display:flex;height:80vh;align-items:center;justify-content:center;color:#9299a3;font-size:25rpx}
</style>
